        static func known(_ fields: GesValueMap, _ names: Set<String>) -> Bool { (0..<fields.length).allSatisfy { names.contains(fields.key(at: $0)) } }

        static func present<T>(_ value: T?, _ encode: (T) -> GesValue) -> GesValue { value.map(encode) ?? .nothing }

        static func optional<T>(_ value: GesValue, _ decode: (GesValue) -> T?) -> T?? { value.isNothing ? .some(nil) : decode(value).map { .some($0) } }

        static func tag(_ name: String) -> GesValue { (try? GesValue.tag(name)) ?? .nothing }

        static func tag(_ value: GesValue) -> String? { value.valueKind == .tag || value.valueKind == .text ? value.textValue : nil }

        static func text(_ value: GesValue) -> String? { value.valueKind == .text ? value.textValue : nil }

        static func boolean(_ value: GesValue) -> Bool? { value.valueKind == .boolean ? value.asBoolean : nil }

        static func percentage(_ value: GesValue) -> Double? { value.valueKind == .percentage ? value.floatValue : nil }

        static func number(_ value: GesValue, _ unit: GesQuantityUnit) -> Double? {
            guard value.unit == unit else { return nil }
            if let integer = value.integerValue { return Double(exactly: integer) }
            return value.valueKind == .float ? value.floatValue : nil
        }

        static func integer(_ value: GesValue, _ unit: GesQuantityUnit) -> Int? {
            guard value.unit == unit else { return nil }
            if let integer = value.integerValue { return Int(exactly: integer) }
            return value.valueKind == .float ? value.floatValue.flatMap { Int(exactly: $0) } : nil
        }

        static func list<T>(_ value: GesValue, _ element: (GesValue) -> T?) -> [T]? {
            guard let items = value.listValue else { return nil }
            var result: [T] = []
            result.reserveCapacity(items.count)
            for item in items {
                guard let decoded = element(item) else { return nil }
                result.append(decoded)
            }
            return result
        }

        static func dice(_ value: GesValue) -> [Int]? { value.diceRolls?.map { Int($0) } }

        static func dice(_ rolls: [Int]) -> GesValue { rolls.allSatisfy { $0 > 0 && $0 <= Int(Int32.max) } ? .dice(rolls.map { Int32($0) }) : .nothing }
    }
}
